function calcPaths(){let F=floors[floor];if(!F?.nav)return;F.distance.fill(30000);let tx=p.x|0,tz=p.z|0;if(inSafe(p.x,p.z)){tx=13;tz=19}let start=tz*WORLD_W+tx;if(!F.nav[start]){let candidate=-1,dist=999;for(let dz=-3;dz<=3;dz++)for(let dx=-3;dx<=3;dx++){let x=tx+dx,z=tz+dz,idx=z*WORLD_W+x;if(x<0||x>=WORLD_W||z<0||z>=WORLD_H||!F.nav[idx])continue;let d=dx*dx+dz*dz;if(d<dist){dist=d;candidate=idx}}if(candidate<0)return;start=candidate;}F.distance[start]=0;let queue=[start],head=0;while(head<queue.length){let c=queue[head++],x=c%WORLD_W,z=c/WORLD_W|0;for(let [dx,dz]of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,nz=z+dz,idx=nz*WORLD_W+nx;if(nx<0||nx>=WORLD_W||nz<0||nz>=WORLD_H||!F.nav[idx]||F.distance[idx]!==30000)continue;if(!zombieLineClear(F,x+.5,z+.5,nx+.5,nz+.5))continue;F.distance[idx]=F.distance[c]+1;queue.push(idx)}}}
