var shotNoise=null;function shoot(){if(state!=='play'||reloadLeft>0||cooldown>0)return;if(ammo===0){reload();return}shotNoise={f:floor,x:p.x,z:p.z,t:elapsed};ammo--;burst(p.x-Math.sin(p.a)*.32,1.45,p.z+Math.cos(p.a)*.32,'#c7a267',1);cooldown=.20;flash=.075;tone(95,.10,.07,'sawtooth');let F=floors[floor],target=null,nearest=70;for(let e of F.enemies){if(e.hp<=0)continue;let d=Math.hypot(e.x-p.x,e.z-p.z),a=Math.atan2(e.z-p.z,e.x-p.x)-p.a;a=Math.atan2(Math.sin(a),Math.cos(a));let height=1.62+Math.tan(p.pitch)*d;if(Math.abs(a)<Math.atan(.32/d)+.008&&height>.15&&height<1.9&&d<nearest&&lineClear(F,p.x,p.z,e.x,e.z)){nearest=d;target=e}}if(!target){for(let d=.7;d<28;d+=.25){let x=p.x+Math.cos(p.a)*d,z=p.z+Math.sin(p.a)*d;if(!walkable(F,x,z,.03)){burst(x-Math.cos(p.a)*.12,1.62+Math.tan(p.pitch)*d,z-Math.sin(p.a)*.12,'#d9ba86',6);break}}}if(target){burst(target.x,1.15,target.z,'#b5ad82',6);target.hp--;target.flash=.13;hit=.14;if(target.hp<=0){kills++;tone(230,.08,.025)}}updateHUD()}
function findAction(){let F=floors[floor],list=[];for(let door of F.doors)if(!door.open){let d=Math.hypot(door.x-p.x,door.z-p.z);if(d<2.25)list.push({type:'door',door,d,text:powerOn?'체육관 문 열기':'체육관 · 전원 복구 필요'})}if(F.med&&Math.hypot(F.med.x-p.x,F.med.z-p.z)<1.9)list.push({type:'heal',d:1,text:'구급함 · 체력 회복'});if(floor===0&&Math.hypot(p.x-F.panel.x,p.z-F.panel.z)<2.4)list.push({type:'panel',d:1,text:powerOn?'전원 복구 완료':remainingZombies()>0?'전원 스위치 · 좀비를 모두 처치해야 작동':'전원 스위치 올리기'});list.sort((a,b)=>a.d-b.d);return list[0]||null}
