function getRoomName(){if(floor===3)return p.x>20&&p.x<24&&p.z>18&&p.z<26?'헬기 기내':'헬기 착륙장';let r=floors[floor]?.rooms.find(r=>p.x>r.x1&&p.x<r.x2&&p.z>r.z1&&p.z<r.z2);return r?r.name:floor===0?'배전실':p.x<1.8?'중앙 계단':p.x>47?'동쪽 연결 복도':p.x>23&&p.x<28&&p.z>18&&p.z<27?'중앙 홀':'본관 복도'}
function update(dt){if(state!=='play')return;elapsed+=dt;powerLevel+=((powerOn?1:0)-powerLevel)*Math.min(1,dt*3.5);powerSurge=Math.max(0,powerSurge-dt);for(let q of particles){q.life-=dt;q.x+=q.vx*dt;q.z+=q.vz*dt;q.y+=q.vy*dt;q.vy-=dt*3.8}particles=particles.filter(q=>q.life>0);cooldown-=dt;flash=Math.max(0,flash-dt);hurt=Math.max(0,hurt-dt*1.5);hit-=dt;noticeTime-=dt;let F=floors[floor];if(reloadLeft>0){reloadLeft-=dt;if(reloadLeft<=0){reloadLeft=0;ammo=18;tone(300,.08)}}let forward=(keys.KeyW?1:0)-(keys.KeyS?1:0)-joy.y,strafe=(keys.KeyD?1:0)-(keys.KeyA?1:0)+joy.x,m=Math.hypot(forward,strafe);if(m>1){forward/=m;strafe/=m}let speed=keys.ShiftLeft?7.8:5.6;move(p,(Math.cos(p.a)*forward-Math.sin(p.a)*strafe)*speed*dt,(Math.sin(p.a)*forward+Math.cos(p.a)*strafe)*speed*dt);updateStairWalk();F=floors[floor];updateMissionBanner(dt);walk+=dt*Math.min(1,m)*9;if(keys.ArrowLeft)p.a-=dt*1.6;if(keys.ArrowRight)p.a+=dt*1.6;if(firing)shoot();navClock-=dt;if(navClock<=0){calcPaths();navClock=.55}updateEnemies(F,dt);if(state!=='play')return;let gym=floors[2].gym;if(floor===2&&powerOn&&remainingZombies()===0&&p.x>gym.x1+.5&&p.x<gym.x2&&p.z>gym.z1&&p.z<gym.z2){finish(true);return}updateHUD()}
