function startRide(){buildRideWorld();state='ride';ride={x:2.2,z:0,heading:-Math.PI/2,speed:0,turn:0,time:0,checkpoint:0,hit:0,caption:4.5};rideInput={left:false,right:false,gas:false,brake:false};for(let id of ['rideLeft','rideRight','rideGas','rideBrake'])$(id).classList.remove('held');keys={};firing=false;resetJoystick();document.exitPointerLock?.();for(let id of ['hud','newsCutscene','result','nextChapter','pauseMenu','menu','ridePause'])$(id).classList.add('hidden');$('rideHud').classList.remove('hidden');$('rideArrival').classList.add('hidden');$('rideDialogue').classList.remove('hidden');rideTraffic=[];for(let i=0;i<23;i++){let d=105+i*54,opposite=i%4===0;rideTraffic.push({d,lane:opposite?-2.2:(i%3===0?6.1:2.2),speed:opposite?-9:(i%3===0?0:12+i%4),color:['#d3d0c0','#536f88','#9c5f4e','#6c8b80'][i%4],long:i%5===0})}last=performance.now();updateRideHUD()}
function pauseRide(){if(state!=='ride')return;state='ridePause';keys={};rideInput={left:false,right:false,gas:false,brake:false};$('ridePause').classList.remove('hidden')}
function resumeRide(){if(state!=='ridePause')return;state='ride';$('ridePause').classList.add('hidden');last=performance.now()}
